<?php
declare(strict_types=1);use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Branches\BranchContextService;use Vendi\Branches\BranchClock;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);$ctx=new BranchContextService($db);$clock=new BranchClock($db);$wanted=$_GET['branch_id']??'all';$allowed=$ctx->available($u);$rows=[];foreach($allowed as$b){if($wanted!=='all'&&(int)$wanted!==(int)$b['id'])continue;$date=$clock->now((int)$u['business_id'],(int)$b['id'])->format('Y-m-d');[$from,$to]=$clock->utcRangeForLocalDate((int)$u['business_id'],(int)$b['id'],$date);$q=$db->prepare("SELECT COUNT(*) tickets,COALESCE(SUM(total),0) sales,COALESCE(SUM(cost_total),0) cost FROM sales WHERE business_id=? AND branch_id=? AND status='completed' AND completed_at_utc>=? AND completed_at_utc<?");$q->execute([(int)$u['business_id'],(int)$b['id'],$from,$to]);$x=$q->fetch();$rows[]=['id'=>(int)$b['id'],'name'=>$b['name'],'timezone'=>$b['timezone'],'local_date'=>$date,'tickets'=>(int)$x['tickets'],'sales'=>(float)$x['sales'],'cost'=>(float)$x['cost'],'profit'=>(float)$x['sales']-(float)$x['cost']];}echo json_encode(['ok'=>true,'branches'=>$allowed,'rows'=>$rows],JSON_UNESCAPED_UNICODE);}catch(Throwable$e){http_response_code(422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}